\text{および}\quad        s + t &= \lambda(1 - r) - 1.  \\
\end{align*}

これらの方程式から、

\begin{gather*}
  s = \frac{\lambda(1 + p - q - r) - 1}{2},  \quad
  t = \frac{\lambda(1 + q - r - p) - 1}{2},  \\
  u = \frac{\lambda(1 + r - p - q) - 1}{2}.  \tag{12}
